    else if (net === 'grpc') { gelSet('nf_grpc_svc', params.serviceName || ''); }
}

function parseHy2(url) {
    var content = url.replace(/^hysteria2?:\/\//, '');
    var name = '';
    var hashIdx = content.indexOf('#');
    if (hashIdx !== -1) { name = decodeURIComponent(content.slice(hashIdx + 1)); content = content.slice(0, hashIdx); }
    var params = {};
    var qIdx = content.indexOf('?');
    if (qIdx !== -1) {
        var qs = content.slice(qIdx + 1);
        content = content.slice(0, qIdx);
        qs.split('&').forEach(function(p) {
            var kv = p.split('=');
            if (kv.length === 2) params[kv[0]] = decodeURIComponent(kv[1]);
        });
    }
    var atIdx = content.indexOf('@');
    var password = decodeURIComponent(content.slice(0, atIdx));
    var serverpart = (content.slice(atIdx + 1) || '').replace(/\/$/, '');
    var address, port;
    if (serverpart.includes(':')) {
        var sp = serverpart.split(':');
        port = parseInt(sp[sp.length - 1]);
        address = sp.slice(0, -1).join(':');
    } else { address = serverpart; port = 443; }

    document.getElementById('nodeProtocol').value = 'hysteria2';
    document.getElementById('nodeName').value = name || address + ':' + port;
    document.getElementById('nodeAddr').value = address;
    document.getElementById('nodePort').value = port;
    onProtoChange();
    gelSet('nf_password', password);
    gelSet('nf_up_mbps', params.upmbps || '');
    gelSet('nf_down_mbps', params.downmbps || '');
    if (params.obfs) { gelSet('nf_obfs_password', params['obfs-password'] || ''); }
}

async function checkSingle(id) {
    try {
        var resp = await fetch('/api/nodes/check', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({node_ids:[id], check_type:'both'}) });
        var data = await resp.json();
        if (data.task_id) { addLog('info', 'Check started for node #' + id); pollCheck(data.task_id); }
        else { addLog('warn', data.message || 'Check rejected'); }
    } catch(e) {}
}

function confirmCheckGroup(gi) {
    var count = groups[gi].nodes.length;
    var name = groups[gi].sub ? groups[gi].sub.name : 'Custom Nodes';
    showConfirm('Check Group', 'Check all ' + count + ' nodes in "' + name + '"?', function() {
        checkGroup(gi);
    }, 'Check');
}

async function checkGroup(gi) {
    var ids = groups[gi].nodes.map(function(n) { return n.id; });
    try {
        var resp = await fetch('/api/nodes/check', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({node_ids:ids, check_type:'both'}) });
        var data = await resp.json();
        if (data.task_id) { addLog('info', 'Bulk check started'); pollCheck(data.task_id); }
        else { addLog('warn', data.message || 'Check rejected'); }
    } catch(e) {}
}

function confirmCheckAll() {
    if (!groups || !groups.length) { addLog('warn', 'No nodes to check'); return; }
    var total = 0;
    groups.forEach(function(g) { total += g.nodes.length; });
    showConfirm('Check All Groups', 'Check all ' + total + ' nodes in ' + groups.length + ' groups?', function() {
        checkAll();
    }, 'Check');
}

async function checkAll() {
    try {
        var resp = await fetch('/api/nodes/check', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({check_type:'both'}) });
        var data = await resp.json();
        if (data.task_id) { addLog('info', 'Full check started'); pollCheck(data.task_id); }
        else { addLog('warn', data.message || 'Check rejected'); }
    } catch(e) {}
}

function pollCheck(taskId) {
    var iv = setInterval(async function() {
        try {
            var resp = await fetch('/api/nodes/check/' + taskId + '/status');
            var data = await resp.json();
            if (!data.running) { clearInterval(iv); loadNodes(); addLog('ok', 'Check completed'); }
        } catch(e) { clearInterval(iv); }
    }, 1500);
}

function confirmDelete(id) {
    document.getElementById('deleteMessage').textContent = 'Delete node #' + id + '?';
    document.getElementById('deleteConfirmBtn').onclick = async function() {
        try {
            await fetch('/api/nodes/' + id, { method: 'DELETE' });
            closeModal('deleteModal');
            loadNodes();
            addLog('ok', 'Node deleted');
        } catch(e) {}
    };
    document.getElementById('deleteModal').classList.add('show');
}

loadNodes();
setInterval(loadNodes, 10000);
</script>
